def checkout(provider, payload, operation_id, deadline, max_attempts):
    for _ in range(max_attempts):
        try:
            return gateway(provider, payload, new_uuid(), deadline)
        except TimeoutError:
            pass
    raise TimeoutError()

sources.gateway.py:
def gateway(provider, payload, key, deadline):
    for _ in range(3):
        try:
            return provider.send(payload, key=key, timeout=deadline)
        except TimeoutError:
            pass
    raise TimeoutError()

